import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { defineConfig } from "vite";

// Dev proxy stands in for the WebView2 bridge: it attaches the agent token
// (generated by the agent on first start) to every /api request so /v1/* auth
// works without the HTML bootstrap injection the production server performs.
const tokenFile = path.join(
  process.env.LOCALAPPDATA ?? path.join(os.homedir(), "AppData", "Local"),
  "OfficeAgent",
  "agent.token"
);

function readAgentToken(): string {
  try {
    return fs.readFileSync(tokenFile, "utf-8").trim();
  } catch {
    return "";
  }
}

export default defineConfig(({ mode }) => {
  const isProd = mode === "production";

  // In production: relative paths, no proxy, agent on same origin
  if (isProd) {
    return {
      base: "./",
      build: {
        outDir: "dist",
        emptyOutDir: true,
      },
      define: {
        __AGENT_BASE__: '""',
      },
    };
  }

  // Development: plain-HTTP dev server (WebView2/browser load http://127.0.0.1,
  // no HTTPS or dev certificates required) proxying to the local agent.
  return {
    server: {
      host: "localhost",
      port: 3001,
      strictPort: true,
      proxy: {
        "/api": {
          target: "http://127.0.0.1:8787",
          changeOrigin: true,
          rewrite: (p) => p.replace(/^\/api/, ""),
          configure: (proxy) => {
            proxy.on("proxyReq", (proxyReq) => {
              const token = readAgentToken();
              if (token) proxyReq.setHeader("X-Agent-Token", token);
            });
          },
        },
      },
    },
    define: {
      __AGENT_BASE__: '"/api"',
    },
  };
});
